  margin: 0 auto;
}

.quiz-container {
  background: var(--bg-card);
  padding: 2rem;
  border-radius: 8px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

h1 {
  margin-top: 0;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
  color: var(--text-main);
}

.form-field {
  margin-bottom: 2.5rem;
}

fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

legend {
  font-weight: 600;
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
  color: var(--text-main);
}

.help-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 0;
  margin-bottom: 1rem;
}

.checkbox-option {
  display: flex;
  align-items: flex-start;
  margin-bottom: 0.75rem;
}

.checkbox-option input[type="checkbox"] {
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
  margin-right: 0.75rem;
  margin-top: 0.125rem;
  accent-color: var(--primary-color);
}

.checkbox-option input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.checkbox-option label {
  font-size: 1rem;
  color: var(--text-main);
  cursor: pointer;
}

.submit-btn {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 500;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.2s;
}

.submit-btn:hover {
  background-color: var(--primary-hover);
}

.submit-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.status-message {
  margin-top: 1.5rem;
  padding: 1rem;
  background-color: var(--success-bg);
  color: var(--success-color);
  border-radius: 4px;
  border: 1px solid var(--success-border);
  font-weight: 500;
}

.status-message p {
  margin: 0;
}
