const http = require('http');
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const PORT = 8080;

const MIME_TYPES = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.css': 'text/css'
};

const server = http.createServer((req, res) => {
  let filePath = '.' + req.url;
  if (filePath === './') {
    filePath = './index.html';
  }

  const extname = String(path.extname(filePath)).toLowerCase();
  const contentType = MIME_TYPES[extname] || 'application/octet-stream';

  fs.readFile(filePath, (error, content) => {
    if (error) {
      if(error.code == 'ENOENT') {
        res.writeHead(404);
        res.end('Not Found');
      }
      else {
        res.writeHead(500);
        res.end('Sorry, check with the site admin for error: '+error.code+' ..\n');
      }
    }
    else {
      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content, 'utf-8');
    }
  });
});

server.listen(PORT, async () => {
  let browser;
  try {
    browser = await chromium.launch();
    const page = await browser.newPage();

    await page.goto(`http://localhost:${PORT}`);

    // Wait for React to render
    await page.waitForSelector('form', { timeout: 10000 });

    await page.addScriptTag({ path: 'node_modules/axe-core/axe.min.js' });
    const r = await page.evaluate(async () => await window.axe.run());

    const wcag = r.violations.filter(v => !(v.tags || []).includes('best-practice'));
    const bp = r.violations.filter(v => (v.tags || []).includes('best-practice'));

    console.log(JSON.stringify({
      wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
      bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }));

    await browser.close();
    server.close();
    if (wcag.length > 0) process.exit(1);
    process.exit(0);
  } catch (e) {
    console.error(e);
    if (browser) await browser.close();
    server.close();
    process.exit(1);
  }
});

