  <script type="text/babel">
    const Quiz = () => {
      const [submitted, setSubmitted] = React.useState(false);

      const handleSubmit = (e) => {
        e.preventDefault();
        setSubmitted(true);
      };

      return (
        <div className="quiz-container">
          <h1>Computer Languages Quiz</h1>

          <form onSubmit={handleSubmit}>

