                  <input type="checkbox" id="q1-java" name="q1" value="java" />
                  <label htmlFor="q1-java">Java</label>
                </div>
                <div className="checkbox-option">
                  <input type="checkbox" id="q1-c" name="q1" value="c" />
                  <label htmlFor="q1-c">C</label>
                </div>
                <div className="checkbox-option">
                  <input type="checkbox" id="q1-cpp" name="q1" value="cpp" />
                  <label htmlFor="q1-cpp">C++</label>
                </div>
                <div className="checkbox-option">
                  <input type="checkbox" id="q1-python" name="q1" value="python" />
                  <label htmlFor="q1-python">Python</label>
                </div>
              </fieldset>
